  1: import type { Theme } from "@earendil-works/pi-coding-agent";
  2: import {
  3:   type Component,
  4:   type Focusable,
  5:   Key,
  6:   matchesKey,
  7:   truncateToWidth,
  8:   visibleWidth,
  9: } from "@earendil-works/pi-tui";
 10: import {
 11:   type HudRow,
 12:   reconcileSelection,
 13:   sections,
 14:   type WorktreeSnapshot,
 15: } from "../state/model.js";
 16: import { planFocusedHudLayout } from "./layout.js";
 17: 
 18: export type HudAction =
 19:   | "row"
 20:   | "stage-all"
 21:   | "unstage-all"
 22:   | "preview"
 23:   | "refresh"
 24:   | "close";
 25: 
 26: interface HudOptions {
 27:   snapshot: () => WorktreeSnapshot | undefined;
 28:   footer: () => string;
 29:   onAction: (action: HudAction, row?: HudRow) => void;
 30:   onInput?: () => void;
 31:   styles: HudStyles;
 32:   maxLines?: () => number;
 33: }
 34: 
 35: type Style = (value: string) => string;
 36: 
 37: export interface HudStyles {
 38:   compactBorder: Style;
 39:   focusedBorder: Style;
 40:   additions: Style;
 41:   deletions: Style;
 42:   text: Style;
 43:   muted: Style;
 44:   section: Record<HudRow["section"], Style>;
 45: }
 46: 
 47: export function createHudStyles(theme: Theme): HudStyles {
 48:   return {
 49:     compactBorder: (value) => theme.fg("borderMuted", value),
 50:     focusedBorder: (value) => theme.fg("borderAccent", value),
 51:     additions: (value) => theme.fg("toolDiffAdded", value),
 52:     deletions: (value) => theme.fg("toolDiffRemoved", value),
 53:     text: (value) => theme.fg("text", value),
 54:     muted: (value) => theme.fg("muted", value),
 55:     section: {
 56:       conflicts: (value) => theme.fg("error", value),
 57:       staged: (value) => theme.fg("success", value),
 58:       changes: (value) => theme.fg("warning", value),
 59:       untracked: (value) => theme.fg("accent", value),
 60:     },
 61:   };
 62: }
 63: 
 64: export class HudComponent implements Component, Focusable {
 65:   readonly #options: HudOptions;
 66:   focused = false;
 67:   selectedId: string | undefined;
 68:   #previousRows: HudRow[] = [];
 69:   #disposed = false;
 70: 
 71:   constructor(options: HudOptions) {
 72:     this.#options = options;
 73:   }
 74: 
 75:   render(width: number): string[] {
 76:     const snapshot = this.#options.snapshot();
 77:     if (!snapshot) return [truncateToWidth("Git · unavailable", width)];
 78:     this.selectedId = reconcileSelection(
 79:       this.#previousRows,
 80:       snapshot.rows,
 81:       this.selectedId,
 82:     );
 83:     this.#previousRows = snapshot.rows;
 84:     if (width < 4)
 85:       return [
 86:         truncateToWidth(`${snapshot.branch} · ${summaryText(snapshot)}`, width),
 87:       ];
 88:     const full = width >= 40;
 89:     const border = this.focused
 90:       ? this.#options.styles.focusedBorder
 91:       : this.#options.styles.compactBorder;
 92:     const summary =
 93:       snapshot.uniqueFileCount === 0
 94:         ? this.#options.styles.text("clean")
 95:         : width < 28
 96:           ? this.#options.styles.text(summaryText(snapshot))
 97:           : full
 98:             ? this.#summary(snapshot)
 99:             : this.#options.styles.text(`${snapshot.uniqueFileCount} files`);
100:     const lines = [
101:       topBorder(`Worktree · ${snapshot.branch}`, width, border),
102:       contentLine(summary, width, border),
103:     ];
104:     if (this.focused) {
105:       const viewport = planFocusedHudLayout(
106:         snapshot.rows,
107:         this.selectedId,
108:         this.#options.maxLines?.() ?? Number.POSITIVE_INFINITY,
109:       );
110:       let previousSection: HudRow["section"] | undefined;
111:       if (viewport.hiddenBefore > 0)
112:         lines.push(
113:           contentLine(
114:             this.#options.styles.muted(`  … ${viewport.hiddenBefore} before`),
115:             width,
116:             border,
117:           ),
118:         );
119:       for (const row of viewport.rows) {
120:         if (row.section !== previousSection) {
121:           const heading = `${sectionTitle(row.section)} ${snapshot.sectionCounts[row.section]}`;
122:           lines.push(
123:             contentLine(
124:               this.#options.styles.section[row.section](heading),
125:               width,
126:               border,
127:             ),
128:           );
129:           previousSection = row.section;
130:         }
131:         const selected = row.id === this.selectedId ? "›" : " ";
132:         const status = row.conflict
133:           ? "UU"
134:           : row.section === "staged"
135:             ? row.indexStatus
136:             : row.worktreeStatus;
137:         lines.push(
138:           contentLine(
139:             `${selected} ${this.#options.styles.section[row.section](status)} ${this.#options.styles.text(row.label)}`,
140:             width,
141:             border,
142:           ),
143:         );
144:       }
145:       if (viewport.hiddenAfter > 0)
146:         lines.push(
147:           contentLine(
148:             this.#options.styles.muted(`  … ${viewport.hiddenAfter} more`),
149:             width,
150:             border,
151:           ),
152:         );
153:       lines.push(bottomBorder(this.#options.footer(), width, border));
154:     } else lines.push(bottomBorder("⌘R", width, border));
155:     return lines.map((line) => truncateToWidth(line, width));
156:   }
157: 
158:   #summary(snapshot: WorktreeSnapshot): string {
159:     const parts = [
160:       this.#options.styles.text(`${snapshot.uniqueFileCount} files`),
161:     ];
162:     if (snapshot.additions > 0)
163:       parts.push(this.#options.styles.additions(`+${snapshot.additions}`));
164:     if (snapshot.deletions > 0)
165:       parts.push(this.#options.styles.deletions(`-${snapshot.deletions}`));
166:     if (snapshot.binaryFileCount > 0)
167:       parts.push(
168:         this.#options.styles.muted(`${snapshot.binaryFileCount} binary`),
169:       );
170:     return parts.join("  ");
171:   }
172: 
173:   handleInput(data: string): void {
174:     if (this.#disposed) return;
175:     this.#options.onInput?.();
176:     const snapshot = this.#options.snapshot();
177:     if (!snapshot) return;
178:     if (matchesKey(data, Key.down) || matchesKey(data, "j"))
179:       this.#move(snapshot.rows, 1);
180:     else if (matchesKey(data, Key.up) || matchesKey(data, "k"))
181:       this.#move(snapshot.rows, -1);
182:     else if (matchesKey(data, Key.tab)) this.#moveSection(snapshot.rows, 1);
183:     else if (matchesKey(data, Key.shift("tab")))
184:       this.#moveSection(snapshot.rows, -1);
185:     else if (matchesKey(data, Key.space))
186:       this.#options.onAction("row", this.#selected(snapshot.rows));
187:     else if (matchesKey(data, Key.shift("a")))
188:       this.#options.onAction("stage-all");
189:     else if (matchesKey(data, Key.shift("u")))
190:       this.#options.onAction("unstage-all");
191:     else if (matchesKey(data, Key.enter))
192:       this.#options.onAction("preview", this.#selected(snapshot.rows));
193:     else if (matchesKey(data, "r")) this.#options.onAction("refresh");
194:     else if (matchesKey(data, Key.escape) || matchesKey(data, "q")) {
195:       this.#options.onAction("close");
196:     }
197:   }
198: 
199:   invalidate(): void {}
200: 
201:   dispose(): void {
202:     this.#disposed = true;
203:     this.#previousRows = [];
204:     this.selectedId = undefined;
205:   }
206: 
207:   #selected(rows: readonly HudRow[]): HudRow | undefined {
208:     return rows.find((row) => row.id === this.selectedId);
209:   }
210: 
211:   #move(rows: readonly HudRow[], delta: number): void {
212:     if (rows.length === 0) return;
213:     const index = Math.max(
214:       0,
215:       rows.findIndex((row) => row.id === this.selectedId),
216:     );
217:     this.selectedId = rows[(index + delta + rows.length) % rows.length].id;
218:   }
219: 
220:   #moveSection(rows: readonly HudRow[], delta: number): void {
221:     const selected = this.#selected(rows);
222:     const start = selected ? sections.indexOf(selected.section) : 0;
223:     for (let offset = 1; offset <= sections.length; offset += 1) {
224:       const section =
225:         sections[
226:           (start + delta * offset + sections.length * 2) % sections.length
227:         ];
228:       const row = rows.find((candidate) => candidate.section === section);
229:       if (row) {
230:         this.selectedId = row.id;
231:         return;
232:       }
233:     }
234:   }
235: }
236: 
237: function summaryText(snapshot: WorktreeSnapshot): string {
238:   return snapshot.uniqueFileCount === 0
239:     ? "clean"
240:     : `${snapshot.uniqueFileCount} changes`;
241: }
242: 
243: function topBorder(title: string, width: number, style: Style): string {
244:   const innerWidth = width - 2;
245:   const label = truncateToWidth(` ${title} `, innerWidth, "…");
246:   const fill = "─".repeat(Math.max(0, innerWidth - visibleWidth(label)));
247:   return style(`╭${label}${fill}╮`);
248: }
249: 
250: function bottomBorder(label: string, width: number, style: Style): string {
251:   const innerWidth = width - 2;
252:   const text = truncateToWidth(` ${label} `, innerWidth, "…");
253:   const fill = "─".repeat(Math.max(0, innerWidth - visibleWidth(text)));
254:   return style(`╰${text}${fill}╯`);
255: }
256: 
257: function contentLine(value: string, width: number, style: Style): string {
258:   return `${style("│")}${truncateToWidth(` ${value}`, width - 2, "…", true)}${style("│")}`;
259: }
260: 
261: function sectionTitle(section: HudRow["section"]): string {
262:   return section === "conflicts"
263:     ? "Conflicts"
264:     : section === "staged"
265:       ? "Staged"
266:       : section === "changes"
267:         ? "Changes"
268:         : "Untracked";
269: }

  1: import type {
  2:   NumstatEntry,
  3:   ParsedNumstat,
  4:   ParsedStatus,
  5:   StatusFile,
  6: } from "./types.js";
  7: 
  8: interface ParserOptions {
  9:   maxRecords?: number;
 10: }
 11: 
 12: function splitPrefix(
 13:   value: string,
 14:   count: number,
 15: ): { fields: string[]; rest: string } | undefined {
 16:   const fields: string[] = [];
 17:   let offset = 0;
 18:   for (let index = 0; index < count; index += 1) {
 19:     const next = value.indexOf(" ", offset);
 20:     if (next < 0) return undefined;
 21:     fields.push(value.slice(offset, next));
 22:     offset = next + 1;
 23:   }
 24:   return { fields, rest: value.slice(offset) };
 25: }
