 27: export class PorcelainV2Parser {
 28:   readonly #decoder = new TextDecoder("utf-8", { fatal: false });
 29:   readonly #maxRecords: number;
 30:   readonly #files: StatusFile[] = [];
 31:   #buffer = "";
 32:   #oid: string | undefined;
 33:   #head: string | undefined;
 34:   #partial = false;
 35:   #truncated = false;
 36:   #pendingRename: Omit<StatusFile, "originalPath"> | undefined;
 37: 
 38:   constructor(options: ParserOptions = {}) {
 39:     this.#maxRecords = options.maxRecords ?? 5_000;
 40:   }
 41: 
 42:   push(chunk: Uint8Array): void {
 43:     this.#buffer += this.#decoder.decode(chunk, { stream: true });
 44:     this.#drain();
 45:   }
 46: 
 47:   markTruncated(): void {
 48:     this.#truncated = true;
 49:   }
 50: 
 51:   finish(): ParsedStatus {
 52:     this.#buffer += this.#decoder.decode();
 53:     this.#drain();
 54:     if (this.#buffer.length > 0 || this.#pendingRename) this.#truncated = true;
 55:     const hasHead = this.#oid !== undefined && this.#oid !== "(initial)";
 56:     const branch = !hasHead
 57:       ? "unborn"
 58:       : this.#head === "(detached)"
 59:         ? `detached@${this.#oid?.slice(0, 7) ?? "unknown"}`
 60:         : (this.#head ?? "unknown");
 61:     return {
 62:       branch,
 63:       hasHead,
 64:       oid: hasHead ? this.#oid : undefined,
 65:       files: this.#files,
 66:       completeness: this.#partial
 67:         ? "partial"
 68:         : this.#truncated
 69:           ? "truncated"
 70:           : "complete",
 71:       recordCount: this.#files.length,
 72:     };
 73:   }
 74: 
 75:   #drain(): void {
 76:     while (true) {
 77:       if (!this.#pendingRename && this.#buffer.startsWith("# ")) {
 78:         const newline = this.#buffer.indexOf("\n");
 79:         const nul = this.#buffer.indexOf("\0");
 80:         const terminator =
 81:           newline < 0 ? nul : nul < 0 ? newline : Math.min(newline, nul);
 82:         if (terminator < 0) return;
 83:         this.#parseHeader(this.#buffer.slice(0, terminator));
 84:         this.#buffer = this.#buffer.slice(terminator + 1);
 85:         continue;
 86:       }
 87:       const nul = this.#buffer.indexOf("\0");
 88:       if (nul < 0) return;
 89:       const record = this.#buffer.slice(0, nul);
 90:       this.#buffer = this.#buffer.slice(nul + 1);
 91:       if (this.#pendingRename) {
 92:         this.#append({ ...this.#pendingRename, originalPath: record });
 93:         this.#pendingRename = undefined;
 94:       } else {
 95:         this.#parseRecord(record);
 96:       }
 97:     }
 98:   }
 99: 
100:   #parseHeader(header: string): void {
101:     if (header.startsWith("# branch.oid ")) this.#oid = header.slice(13);
102:     if (header.startsWith("# branch.head ")) this.#head = header.slice(14);
103:   }
104: 
105:   #parseRecord(record: string): void {
106:     if (record.startsWith("? ")) {
107:       this.#append({
108:         recordType: "?",
109:         path: record.slice(2),
110:         indexStatus: "?",
111:         worktreeStatus: "?",
112:         conflict: false,
113:       });
114:       return;
115:     }
116:     const kind = record[0];
117:     if (kind !== "1" && kind !== "2" && kind !== "u") {
118:       this.#partial = true;
119:       return;
120:     }
121:     const prefixCount = kind === "1" ? 8 : kind === "2" ? 9 : 10;
122:     const split = splitPrefix(record, prefixCount);
123:     if (!split || split.fields[0] !== kind || split.fields[1]?.length !== 2) {
124:       this.#partial = true;
125:       return;
126:     }
127:     const file: StatusFile = {
128:       recordType: kind,
129:       path: split.rest,
130:       indexStatus: split.fields[1][0],
131:       worktreeStatus: split.fields[1][1],
132:       conflict: kind === "u",
133:       submodule: split.fields[2],
134:       indexOid: kind === "u" ? split.fields[8] : split.fields[7],
135:     };
136:     if (kind === "2") this.#pendingRename = file;
137:     else this.#append(file);
138:   }
139: 
140:   #append(file: StatusFile): void {
141:     if (this.#files.length >= this.#maxRecords) {
142:       this.#truncated = true;
143:       return;
144:     }
145:     this.#files.push(file);
146:   }
147: }
