149: export class NumstatParser {
150:   readonly #decoder = new TextDecoder("utf-8", { fatal: false });
151:   readonly #maxRecords: number;
152:   readonly #entries: NumstatEntry[] = [];
153:   #buffer = "";
154:   #pendingRename:
155:     | {
156:         additions: number | null;
157:         deletions: number | null;
158:         originalPath?: string;
159:       }
160:     | undefined;
161:   #additions = 0;
162:   #deletions = 0;
163:   #binaryFileCount = 0;
164:   #truncated = false;
165: 
166:   constructor(options: ParserOptions = {}) {
167:     this.#maxRecords = options.maxRecords ?? 5_000;
168:   }
169: 
170:   push(chunk: Uint8Array): void {
171:     this.#buffer += this.#decoder.decode(chunk, { stream: true });
172:     this.#drain();
173:   }
174: 
175:   markTruncated(): void {
176:     this.#truncated = true;
177:   }
178: 
179:   finish(): ParsedNumstat {
180:     this.#buffer += this.#decoder.decode();
181:     this.#drain();
182:     if (this.#buffer.length > 0 || this.#pendingRename) this.#truncated = true;
183:     return {
184:       additions: this.#additions,
185:       deletions: this.#deletions,
186:       binaryFileCount: this.#binaryFileCount,
187:       entries: this.#entries,
188:       truncated: this.#truncated,
189:     };
190:   }
191: 
192:   #drain(): void {
193:     while (true) {
194:       const nul = this.#buffer.indexOf("\0");
195:       if (nul < 0) return;
196:       const part = this.#buffer.slice(0, nul);
197:       this.#buffer = this.#buffer.slice(nul + 1);
198:       if (this.#pendingRename) {
199:         if (this.#pendingRename.originalPath === undefined) {
200:           this.#pendingRename.originalPath = part;
201:         } else {
202:           this.#append({ ...this.#pendingRename, path: part });
203:           this.#pendingRename = undefined;
204:         }
205:         continue;
206:       }
207:       const firstTab = part.indexOf("\t");
208:       const secondTab = part.indexOf("\t", firstTab + 1);
209:       if (firstTab < 0 || secondTab < 0) {
210:         this.#truncated = true;
211:         continue;
212:       }
213:       const additions =
214:         part.slice(0, firstTab) === "-"
215:           ? null
216:           : Number(part.slice(0, firstTab));
217:       const deletions =
218:         part.slice(firstTab + 1, secondTab) === "-"
219:           ? null
220:           : Number(part.slice(firstTab + 1, secondTab));
221:       const path = part.slice(secondTab + 1);
222:       if (!Number.isFinite(additions) && additions !== null)
223:         this.#truncated = true;
224:       else if (!Number.isFinite(deletions) && deletions !== null)
225:         this.#truncated = true;
226:       else if (path === "") this.#pendingRename = { additions, deletions };
227:       else this.#append({ additions, deletions, path });
228:     }
229:   }
230: 
231:   #append(entry: NumstatEntry): void {
232:     if (this.#entries.length >= this.#maxRecords) {
233:       this.#truncated = true;
234:       return;
235:     }
236:     this.#entries.push(entry);
237:     if (entry.additions === null || entry.deletions === null)
238:       this.#binaryFileCount += 1;
239:     else {
240:       this.#additions += entry.additions;
241:       this.#deletions += entry.deletions;
242:     }
243:   }
244: }

  1: import type { Completeness, StatusFile } from "../git/types.js";
  2: 
  3: export const sections = [
  4:   "conflicts",
  5:   "staged",
  6:   "changes",
  7:   "untracked",
  8: ] as const;
  9: export type Section = (typeof sections)[number];
 10: 
 11: export interface HudRow {
 12:   id: string;
 13:   section: Section;
 14:   path: string;
 15:   originalPath?: string;
 16:   label: string;
 17:   indexStatus: string;
 18:   worktreeStatus: string;
 19:   conflict: boolean;
 20:   indexOid?: string;
 21: }
 22: 
 23: export interface WorktreeSnapshot {
 24:   generation: number;
 25:   root: string;
 26:   branch: string;
 27:   hasHead: boolean;
 28:   files: StatusFile[];
 29:   rows: HudRow[];
 30:   uniqueFileCount: number;
 31:   sectionCounts: Record<Section, number>;
 32:   additions: number;
 33:   deletions: number;
 34:   binaryFileCount: number;
 35:   completeness: Completeness;
 36:   freshness: "current" | "stale";
 37:   capturedAt: number;
 38:   statsCapturedAt?: number;
 39:   lastError?: string;
 40: }
 41: 
 42: export interface SnapshotInput {
 43:   generation: number;
 44:   root: string;
 45:   branch: string;
 46:   hasHead: boolean;
 47:   files: StatusFile[];
 48:   completeness: Completeness;
 49:   additions?: number;
 50:   deletions?: number;
 51:   binaryFileCount?: number;
 52:   capturedAt?: number;
 53:   statsCapturedAt?: number;
 54: }
 55: 
 56: function unicodeCompare(left: string, right: string): number {
 57:   return left < right ? -1 : left > right ? 1 : 0;
 58: }
 59: 
 60: function row(section: Section, file: StatusFile): HudRow {
 61:   return {
 62:     id: `${section}\0${file.path}\0${file.originalPath ?? ""}`,
 63:     section,
 64:     path: file.path,
 65:     originalPath: file.originalPath,
 66:     label: file.originalPath
 67:       ? `${file.originalPath} → ${file.path}`
 68:       : file.path,
 69:     indexStatus: file.indexStatus,
 70:     worktreeStatus: file.worktreeStatus,
 71:     conflict: file.conflict,
 72:     indexOid: file.indexOid,
 73:   };
 74: }
 75: 
 76: export function buildRows(files: readonly StatusFile[]): HudRow[] {
 77:   const buckets = new Map<Section, HudRow[]>(
 78:     sections.map((section) => [section, []]),
 79:   );
 80:   for (const file of files) {
 81:     if (file.conflict) buckets.get("conflicts")?.push(row("conflicts", file));
 82:     else if (file.recordType === "?")
 83:       buckets.get("untracked")?.push(row("untracked", file));
 84:     else {
 85:       if (file.indexStatus !== ".")
 86:         buckets.get("staged")?.push(row("staged", file));
 87:       if (file.worktreeStatus !== ".")
 88:         buckets.get("changes")?.push(row("changes", file));
 89:     }
 90:   }
 91:   return sections.flatMap((section) =>
 92:     (buckets.get(section) ?? []).sort((left, right) => {
 93:       const pathOrder = unicodeCompare(left.path, right.path);
 94:       return (
 95:         pathOrder ||
 96:         unicodeCompare(left.originalPath ?? "", right.originalPath ?? "")
 97:       );
 98:     }),
 99:   );
100: }
101: 
102: export function buildSnapshot(input: SnapshotInput): WorktreeSnapshot {
103:   const rows = buildRows(input.files);
104:   const sectionCounts = Object.fromEntries(
105:     sections.map((section) => [section, 0]),
106:   ) as Record<Section, number>;
107:   for (const current of rows) sectionCounts[current.section] += 1;
108:   return {
109:     ...input,
110:     rows,
111:     uniqueFileCount: new Set(input.files.map((file) => file.path)).size,
112:     sectionCounts,
113:     additions: input.additions ?? 0,
114:     deletions: input.deletions ?? 0,
115:     binaryFileCount: input.binaryFileCount ?? 0,
116:     freshness: "current",
117:     capturedAt: input.capturedAt ?? Date.now(),
118:   };
119: }
120: 
121: export function reconcileSelection(
122:   previousRows: readonly HudRow[],
123:   nextRows: readonly HudRow[],
124:   selectedId: string | undefined,
125: ): string | undefined {
126:   if (nextRows.length === 0) return undefined;
127:   if (!selectedId) return nextRows[0].id;
128:   if (nextRows.some((row) => row.id === selectedId)) return selectedId;
129:   const oldIndex = previousRows.findIndex((row) => row.id === selectedId);
130:   if (oldIndex < 0) return nextRows[0].id;
131:   const oldSection = previousRows[oldIndex].section;
132:   const oldSectionIndex = previousRows
133:     .slice(0, oldIndex)
134:     .filter((row) => row.section === oldSection).length;
135:   const sameSection = nextRows.filter((row) => row.section === oldSection);
136:   if (sameSection.length > 0)
137:     return sameSection[Math.min(oldSectionIndex, sameSection.length - 1)].id;
138:   const sectionIndex = sections.indexOf(oldSection);
139:   for (let offset = 1; offset <= sections.length; offset += 1) {
140:     const candidate = sections[(sectionIndex + offset) % sections.length];
141:     const first = nextRows.find((row) => row.section === candidate);
142:     if (first) return first.id;
143:   }
144:   return nextRows[0].id;
145: }
146: 
147: export function sectionWindow(
148:   rows: readonly HudRow[],
149:   selectedId: string | undefined,
150:   capacity: number,
151: ): { rows: HudRow[]; hiddenBefore: number; hiddenAfter: number } {
152:   const safeCapacity = Math.max(0, capacity);
153:   if (rows.length <= safeCapacity)
154:     return { rows: [...rows], hiddenBefore: 0, hiddenAfter: 0 };
155:   const selectedIndex = Math.max(
156:     0,
157:     rows.findIndex((row) => row.id === selectedId),
158:   );
159:   const start = Math.min(
160:     Math.max(0, selectedIndex - Math.floor(safeCapacity / 2)),
161:     rows.length - safeCapacity,
162:   );
163:   return {
164:     rows: rows.slice(start, start + safeCapacity),
165:     hiddenBefore: start,
166:     hiddenAfter: rows.length - start - safeCapacity,
167:   };
168: }
