170: export function markSnapshotStale(
171:   snapshot: WorktreeSnapshot,
172:   error: string,
173: ): WorktreeSnapshot {
174:   return { ...snapshot, freshness: "stale", lastError: error };
175: }
176: 
177: export function mutationsAllowed(
178:   snapshot: WorktreeSnapshot | undefined,
179: ): boolean {
180:   return Boolean(
181:     snapshot &&
182:       snapshot.freshness === "current" &&
183:       snapshot.completeness !== "partial",
184:   );
185: }

