  4: function chunks(value: string, sizes: number[]): Uint8Array[] {
  5:   const bytes = new TextEncoder().encode(value);
  6:   const result: Uint8Array[] = [];
  7:   let offset = 0;
  8:   for (const size of sizes) {
  9:     result.push(bytes.slice(offset, offset + size));
 10:     offset += size;
 11:   }
 12:   if (offset < bytes.length) result.push(bytes.slice(offset));
 13:   return result;
 14: }
